def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    row_spans = [(row_bounds[i] + 1, row_bounds[i + 1]) for i in range(len(row_bounds) - 1)]
    col_spans = [(col_bounds[i] + 1, col_bounds[i + 1]) for i in range(len(col_bounds) - 1)]
    sep_colors = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}
    freq = {}
    for row in grid:
        for value in row:
            freq[value] = freq.get(value, 0) + 1
    bg = max(freq, key=freq.get)

    # The panel carrying the sparse colored pattern is the source motif.
    motif_choice = None
    max_marks = -1
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            marks = [(dr, dc, grid[r0 + dr][c0 + dc])
                     for dr in range(r1 - r0) for dc in range(c1 - c0)
                     if grid[r0 + dr][c0 + dc] != bg
                     and grid[r0 + dr][c0 + dc] not in sep_colors]
            if len(marks) > max_marks:
                max_marks = len(marks)
                motif_choice = (ri, ci, marks)
    sri, sci, motif = motif_choice
    sh = row_spans[sri][1] - row_spans[sri][0]
    sw = col_spans[sci][1] - col_spans[sci][0]
    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            if r1 - r0 != sh or c1 - c0 != sw:
                continue
            for dr, dc, value in motif:
                # Panels on the opposite side of the vertical divider receive
                # the horizontally reflected version of the motif.
                out[r0 + dr][c0 + dc] = value
    return out

